import { BP, SIZE_COL_NAV } from 'app/theme/components/footerShared';

export const ZimmFooterBottomBar = {
  parts: ['bar', 'inner', 'right', 'copyright', 'legalLink', 'legalGrid', 'localeText', 'localeButton'],
  baseStyle: {
    bar: {
      backgroundColor: 'var(--zimm-color-bg-06)',
      width: '100%',
    },

    // Figma: stacked column on mobile, single row on tablet+
    inner: {
      display: 'flex',
      flexDirection: 'column',
      alignItems: 'flex-start',
      gap: 0,
      padding: 'var(--zimm-scale-xl) var(--zimm-scale-2xl)',
      [`@media (min-width: ${BP.tablet})`]: {
        flexDirection: 'row',
        alignItems: 'center',
        justifyContent: 'space-between',
        // Gutter widens here, not at BP.desktop. footer.css.ts's contentRow and logo both step
        // from 2xl to 3xl at BP.tablet, so holding this at 2xl until 1024px left the whole
        // 768-1023px band with the bottom bar inset 8px less than the content above it — the
        // locale control and the legal links sat left of the subscribe column and the logo.
        padding: 'var(--zimm-scale-xl) var(--zimm-scale-3xl)',
      },
    },

    // Right group: copyright span + legalGrid div stacked on mobile, flex-row on tablet.
    // copyright is a direct flex child (no wrapper div) to match Figma's flat Legal row.
    right: {
      display: 'flex',
      flexDirection: 'column',
      alignItems: 'flex-start',
      gap: 'var(--zimm-scale-xs)',
      width: '100%',
      [`@media (min-width: ${BP.tablet})`]: {
        flexDirection: 'row',
        alignItems: 'center',
        justifyContent: 'flex-end',
        gap: `0 var(--zimm-scale-xl)`,
        width: 'auto',
      },
      [`@media (min-width: ${BP.desktop})`]: {
        gap: `0 var(--zimm-scale-2xl)`,
      },
    },

    // Copyright + legal links share the footer text style; py-8px matches Figma Small/Default.
    copyright: {
      textStyle: 'footer',
      color: 'var(--zimm-color-text-muted)',
      whiteSpace: 'nowrap',
      paddingY: 'var(--zimm-scale-xs)',
      paddingX: 0,
    },
    legalLink: {
      textStyle: 'footer',
      color: 'var(--zimm-color-text-muted)',
      justifyContent: 'flex-start',
      // No height override — ZimmNavItem's baseStyle uses minHeight, so the py-8px below grows
      // the item naturally. Figma Small/Default: py-[8px].
      paddingY: 'var(--zimm-scale-xs)',
      paddingX: 0,
    },

    // Legal links: 2-col flex-wrap grid on mobile; inline flex row inside `right` at tablet+.
    // Avoids display:contents (unreliable in Emotion __css media queries) — legalGrid stays a
    // normal flex container but switches from a full-width wrap to an auto-width nowrap row.
    legalGrid: {
      display: 'flex',
      flexWrap: 'wrap',
      alignContent: 'flex-start',
      gap: `0 var(--zimm-scale-3xl)`,
      width: '100%',
      '& > a': { width: SIZE_COL_NAV },
      [`@media (min-width: ${BP.tablet})`]: {
        flexWrap: 'nowrap',
        gap: `0 var(--zimm-scale-xl)`,
        width: 'auto',
        '& > a': { width: 'auto' },
      },
      [`@media (min-width: ${BP.desktop})`]: {
        gap: `0 var(--zimm-scale-2xl)`,
      },
    },

    // Locale button inner text span — py-8px at EVERY breakpoint. Figma's Language item is h=23
    // (8px + 7px text + 8px) identically on desktop (40000407:14372) and mobile
    // (40000407:23934), and its Legal row opposite is also h=23, so both ends of the bottom bar
    // share a height. A previous tablet+ `padding: 0` override collapsed this to 14px against
    // the 31px legal links — removed.
    localeText: {
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      paddingY: 'var(--zimm-scale-xs)',
      paddingX: 0,
      whiteSpace: 'nowrap',
    },

    // textStyle: 'footer' consolidates: FONT_MEDIUM / 10px / 500 / 14px / 0.4px / uppercase.
    // No cursor/_focusVisible here: index.tsx renders this on a non-interactive div (see the
    // PLACEHOLDER comment there), and a pointer cursor or focus ring would promise an action
    // the control cannot perform (WCAG 3.2.4). Restore both when it becomes a real button.
    localeButton: {
      textStyle: 'footer',
      color: 'var(--zimm-color-text-inverse)',
      display: 'inline-flex',
      alignItems: 'center',
      gap: 'var(--zimm-scale-2xs)',
      background: 'none',
      border: 'none',
      padding: 0,
      whiteSpace: 'nowrap',
    },
  },
};

