+    let inSingle = false
+    let inDouble = false
+    let i = 0
+    while (i < line.length) {
+      const ch = line[i]
+      if (inBlock) {
+        if (ch === '*' && line[i + 1] === '/') { inBlock = false; i += 2; continue }
+      } else if (inSingle) {
+        if (ch === '\\') { i += 2; continue } // skip escape sequence
