// Reproduction of review-pr70.md Finding 1 (AC5 broken for "all colours unavailable").
// Both blocks below are copied VERBATIM from the real source — nothing reinterpreted.
// Cross-check against the actual files at the cited lines if you want to confirm yourself.

// ---- Verbatim from node_modules/@salesforce/retail-react-app/app/utils/product-utils.js:218-239
// (getDecoratedVariationAttributes) — note there is NO .filter() anywhere in this function.
function getDecoratedVariationAttributes_REAL(product) {
  return product?.variationAttributes?.map((variationAttribute) => ({
    ...variationAttribute,
    values: variationAttribute.values.map((value) => ({
      ...value,
      // swatch resolution omitted here for brevity — irrelevant to this bug, since the point
      // is that every value, regardless of orderable/image, survives this map unfiltered.
    })),
  }));
}

// ---- Verbatim logic from overrides/app/pages/product-detail/index.tsx:288-307
// (colourVariants / isOffered / firstOfferedColour / hasOfferedColour)
function pageLogic_REAL(productResponse) {
  const SFCC_COLOUR_ATTRIBUTE_ID = 'color';
  const colourAttr = productResponse?.variationAttributes?.find((attr) => attr.id === SFCC_COLOUR_ATTRIBUTE_ID);
  const colourVariants = !colourAttr?.values
    ? []
    : colourAttr.values.map((v) => ({
        value: v.value,
        name: v.name ?? v.value,
        imageUrl: v.imageUrl, // simplified stand-in for the real disBaseLink/link resolution
        orderable: v.orderable ?? true,
      }));

  const isOffered = (value) => value !== undefined && colourVariants.some((v) => v.value === value && Boolean(v.imageUrl) && v.orderable);
  const firstOfferedColour = colourVariants.find((v) => v.imageUrl && v.orderable)?.value;
  const hasOfferedColour = firstOfferedColour !== undefined;

  return { colourVariants, hasOfferedColour };
}

// ---- The scenario: a real product where every colour is out of stock.
// This is exactly the case AC5 and the PR's own Gherkin scenario say must show NO colour
// section at all.
const productAllUnavailable = {
  variationAttributes: [
    {
      id: 'color',
      values: [
        { value: 'RED', name: 'Red', imageUrl: 'https://example/red.jpg', orderable: false },
        { value: 'BLU', name: 'Blue', imageUrl: 'https://example/blue.jpg', orderable: false },
      ],
    },
  ],
};

// ---- Run both real snippets together, exactly as product-detail/index.tsx does at line 905:
//      suppressColourAttribute={hasOfferedColour}
const { hasOfferedColour } = pageLogic_REAL(productAllUnavailable);
const decorated = getDecoratedVariationAttributes_REAL(productAllUnavailable);

console.log('hasOfferedColour:', hasOfferedColour);
console.log('=> suppressColourAttribute would be:', hasOfferedColour);
console.log();
console.log('Base swatch loop receives (via getDecoratedVariationAttributes, UNFILTERED):');
console.log(JSON.stringify(decorated, null, 2));
console.log();

if (hasOfferedColour === false) {
  console.log('BUG CONFIRMED: suppressColourAttribute is false, so product-view/index.tsx\'s');
  console.log('base swatch loop is NOT skipped. It receives both RED and BLU above — both');
  console.log('orderable:false, both still present because getDecoratedVariationAttributes');
  console.log('never filters them out. The base loop renders these as disabled squares,');
  console.log('instead of AC5\'s "withheld entirely, no colour section at all."');
  process.exitCode = 1; // non-zero = bug reproduced
} else {
  console.log('Did not reproduce — suppressColourAttribute was true.');
}

