import { describe, test, expect } from 'vitest';
import { computeAccessibleName } from 'dom-accessibility-api';

// Throwaway probe, not part of the suite — demonstrates, using the same accessible-name
// computation algorithm real assistive tech relies on, that a non-empty alt on an image
// inside an already-labelled button produces TWO separate accessibility-tree nodes carrying
// the identical name, vs. alt="" producing only ONE.

describe('alt text repeated-read probe', () => {
  test('non-empty alt: BOTH the button and the image compute the same accessible name', () => {
    document.body.innerHTML = `
      <button aria-label="Bay Blue">
        <img src="swatch.jpg" alt="Bay Blue" />
      </button>
    `;
    const button = document.querySelector('button')!;
    const img = document.querySelector('img')!;

    const buttonName = computeAccessibleName(button);
    const imgName = computeAccessibleName(img);

    console.log('--- alt="Bay Blue" (non-empty) ---');
    console.log('button accessible name:', JSON.stringify(buttonName));
    console.log('img accessible name:   ', JSON.stringify(imgName));

    // Both nodes independently carry the name "Bay Blue" — two accessible-tree entries,
    // same content, which is the measurable root cause of a screen reader announcing it twice.
    expect(buttonName).toBe('Bay Blue');
    expect(imgName).toBe('Bay Blue');
  });

  test('alt="": only the button carries a name, the image has none', () => {
    document.body.innerHTML = `
      <button aria-label="Bay Blue">
        <img src="swatch.jpg" alt="" />
      </button>
    `;
    const button = document.querySelector('button')!;
    const img = document.querySelector('img')!;

    const buttonName = computeAccessibleName(button);
    const imgName = computeAccessibleName(img);

    console.log('--- alt="" (empty/decorative) ---');
    console.log('button accessible name:', JSON.stringify(buttonName));
    console.log('img accessible name:   ', JSON.stringify(imgName));

    expect(buttonName).toBe('Bay Blue');
    expect(imgName).toBe(''); // no separate name — the image contributes nothing to announce
  });
});

